import argparse
from typing import Any

from fastapi import FastAPI, Header, HTTPException
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field

from app.rules import order_rules
from app.store import imports, orders, search
from app.store.db import connect, migrate

app = FastAPI(title="settlement-ledger")

class OrderIn(BaseModel):
    tenant: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)
    currency: str = Field(min_length=3, max_length=3)

class PaymentIn(BaseModel):
    amount_cents: int = Field(gt=0)

class RefundIn(BaseModel):
    biz_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)

class BatchIn(BaseModel):
    rows: list[Any] = Field(min_length=1)

class SearchIn(BaseModel):
    request_id: str = Field(min_length=1)
    filters: dict | None = None
    page: dict | None = None

@app.get("/health")
def health() -> dict:
    conn = connect()
    try:
        conn.execute("SELECT 1")
    finally:
        conn.close()
    return {"status": "ok"}

@app.post("/orders", status_code=201)
def create_order(body: OrderIn) -> dict:
    order_rules.assert_currency(body.currency)
    try:
        orders.insert(body.tenant, body.order_id, body.amount_cents, body.currency)
    except Exception as error:
        if "UNIQUE" in str(error):
            raise HTTPException(status_code=409, detail="order already accepted")
        raise
    return orders.get(body.tenant, body.order_id)

@app.post("/orders/batch")
def accept_batch(body: BatchIn) -> dict:
    results = imports.accept_batch(body.rows)
    accepted = sum(1 for item in results if item["status"] == "accepted")
    return {"accepted": accepted, "rejected": len(results) - accepted, "results": results}

@app.post("/orders/search")
def search_orders(body: SearchIn, x_tenant: str = Header(default="")) -> JSONResponse:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    try:
        filters = order_rules.normalize_filters(body.filters)
        size, cursor = order_rules.normalize_page(body.page)
    except (ValueError, TypeError) as error:
        raise HTTPException(status_code=400, detail=str(error))
    response, replayed = search.run_search(x_tenant, body.request_id, filters, size, cursor)
    response["replayed"] = replayed
    return JSONResponse(  # 重放返回首次的同一结果集，保持 200 与首调一致
        response,
        headers={"X-Idempotent-Replay": "1" if replayed else "0"},
    )

@app.get("/orders/{order_id}")
def read_order(order_id: str, x_tenant: str = Header(default="", alias=None)) -> dict:
    tenant = x_tenant or ""
    if not tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    order = orders.get(tenant, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/payments")
def add_payment(order_id: str, body: PaymentIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    try:
        return orders.add_payment(x_tenant, order_id, body.amount_cents)
    except LookupError:
        raise HTTPException(status_code=404, detail="order not found")
    except ValueError as error:
        raise HTTPException(status_code=409, detail=str(error))

@app.post("/orders/{order_id}/refunds")
def add_refund(order_id: str, body: RefundIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    try:
        refund, replayed = orders.add_refund(x_tenant, order_id, body.biz_id, body.amount_cents)
    except LookupError:
        raise HTTPException(status_code=404, detail="order not found")
    except ValueError as error:
        raise HTTPException(status_code=409, detail=str(error))
    return JSONResponse(  # 重放返回同一记录，保持 200 与首调一致
        refund,
        headers={"X-Idempotent-Replay": "1" if replayed else "0"},
    )

@app.get("/orders/{order_id}/ledger")
def read_ledger(order_id: str, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    entries = orders.list_ledger(x_tenant, order_id)
    if entries is None:
        raise HTTPException(status_code=404, detail="order not found")
    return {"order_id": order_id, "entries": entries}

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--migrate", action="store_true")
    args = parser.parse_args()
    migrate()
    if args.migrate:
        print("migrated")
        return
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=args.port)

if __name__ == "__main__":
    main()

ALLOWED_CURRENCIES = {"CNY", "USD", "EUR", "JPY"}

ORDER_STATUSES = {"accepted", "settled", "completed"}

# 金额区间筛选字段：筛选参数名 -> 订单列名
RANGE_FILTERS = {
    "amount": "amount_cents",
    "paid": "paid_cents",
    "refunded": "refunded_cents",
}

PAGE_SIZE_DEFAULT = 50
PAGE_SIZE_MAX = 500

def assert_currency(currency: str) -> None:
    if currency not in ALLOWED_CURRENCIES:
        raise ValueError("unsupported currency")

def _is_int(value: object) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)

def normalize_filters(filters: object) -> dict:
    """校验并规范化检索条件；非法条件抛 ValueError/TypeError（可区分原因）。"""
    if filters is None:
        return {}
    if not isinstance(filters, dict):
        raise TypeError("invalid_filters")
    known = {"status", "currency", "has_refund"} | {
        f"{name}_{bound}_cents" for name in RANGE_FILTERS for bound in ("min", "max")
    }
    unknown = set(filters) - known
    if unknown:
        raise ValueError(f"unknown_filter:{min(unknown)}")
    out: dict = {}
    status = filters.get("status")
    if status is not None:
        if status not in ORDER_STATUSES:
            raise ValueError("invalid_status")
        out["status"] = status
    currency = filters.get("currency")
    if currency is not None:
        if currency not in ALLOWED_CURRENCIES:
            raise ValueError("unsupported_currency")
        out["currency"] = currency
    for name in RANGE_FILTERS:
        lo = filters.get(f"{name}_min_cents")
        hi = filters.get(f"{name}_max_cents")
        for value in (lo, hi):
            if value is not None and (not _is_int(value) or value < 0):
                raise ValueError(f"invalid_{name}_range")
        if lo is not None and hi is not None and lo > hi:
            raise ValueError(f"invalid_{name}_range")
        if lo is not None:
            out[f"{name}_min_cents"] = lo
        if hi is not None:
            out[f"{name}_max_cents"] = hi
    has_refund = filters.get("has_refund")
    if has_refund is not None:
        if not isinstance(has_refund, bool):
            raise ValueError("invalid_has_refund")
        out["has_refund"] = has_refund
    return out

def normalize_page(page: object) -> tuple[int, str | None]:
    """校验并规范化分页参数，返回 (size, cursor)；非法抛 ValueError/TypeError。"""
    if page is None:
        return PAGE_SIZE_DEFAULT, None
    if not isinstance(page, dict):
        raise TypeError("invalid_page")
    unknown = set(page) - {"size", "cursor"}
    if unknown:
        raise ValueError(f"unknown_page_field:{min(unknown)}")
    size = page.get("size", PAGE_SIZE_DEFAULT)
    if not _is_int(size) or size < 1 or size > PAGE_SIZE_MAX:
        raise ValueError("invalid_page_size")
    cursor = page.get("cursor")
    if cursor is not None and not isinstance(cursor, str):
        raise ValueError("invalid_cursor")
    return size, cursor

from app.rules.order_rules import ALLOWED_CURRENCIES
from app.store import orders

# 行级拒绝原因（可区分）
REASON_INVALID_ROW = "invalid_row"                # 行不是对象
REASON_MISSING_FIELD = "missing_field"            # 必填标识缺失或为空
REASON_INVALID_AMOUNT = "invalid_amount"          # 金额非正整数
REASON_UNSUPPORTED_CURRENCY = "unsupported_currency"
REASON_DUPLICATE_IN_BATCH = "duplicate_in_batch"  # 同一份提交内重复
REASON_DUPLICATE_ACCEPTANCE = "duplicate_acceptance"  # 订单标识已存在

def _reject(line: int, reason: str, row: dict | None = None) -> dict:
    result = {"line": line, "status": "rejected", "reason": reason}
    if isinstance(row, dict):
        result["tenant"] = row.get("tenant")
        result["order_id"] = row.get("order_id")
    return result

def _accept_row(line: int, row: object, seen: set[tuple[str, str]]) -> dict:
    if not isinstance(row, dict):
        return _reject(line, REASON_INVALID_ROW)
    tenant = row.get("tenant")
    order_id = row.get("order_id")
    if (
        not isinstance(tenant, str) or not tenant.strip()
        or not isinstance(order_id, str) or not order_id.strip()
    ):
        return _reject(line, REASON_MISSING_FIELD, row)
    key = (tenant, order_id)
    if key in seen:
        # 同一份提交内重复出现：只按第一次生效，重复行拒绝
        return _reject(line, REASON_DUPLICATE_IN_BATCH, row)
    seen.add(key)
    amount = row.get("amount_cents")
    if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
        return _reject(line, REASON_INVALID_AMOUNT, row)
    currency = row.get("currency")
    if not isinstance(currency, str) or currency not in ALLOWED_CURRENCIES:
        return _reject(line, REASON_UNSUPPORTED_CURRENCY, row)
    try:
        orders.insert(tenant, order_id, amount, currency)
    except Exception as error:
        if "UNIQUE" in str(error):
            # 订单标识已存在：重复受理拒绝，不修改已有订单与流水
            return _reject(line, REASON_DUPLICATE_ACCEPTANCE, row)
        raise
    return {
        "line": line,
        "status": "accepted",
        "tenant": tenant,
        "order_id": order_id,
        "order": orders.get(tenant, order_id),
    }

def accept_batch(rows: list) -> list[dict]:
    """逐行校验并以行为单位独立生效；某行被拒绝不影响其他行，也不产生流水。"""
    seen: set[tuple[str, str]] = set()
    return [_accept_row(line, row, seen) for line, row in enumerate(rows, start=1)]

